// The invoice fixture (fixtures/docs/invoice.json, generated by
// scripts/fixtures/invoice.py) built in TypeScript against the
// @inkoxide/schema types, the way a client app builds documents.
import type { BoxNode, Color, Document, Node, Style, TextNode, TextRun } from '@inkoxide/schema';

const INK: Color = [0.09, 0.1, 0.13, 1];
const MUTED: Color = [0.42, 0.45, 0.52, 1];
const LINE: Color = [0.88, 0.89, 0.92, 1];
const ACCENT: Color = [0.16, 0.36, 0.86, 1];
const WASH: Color = [0.96, 0.97, 0.99, 1];

const run = (
  text: string,
  font = 'Inter-Regular',
  size = 9,
  color: Color = INK,
  extra: Partial<TextRun> = {},
): TextRun => ({ text, font, size, color, ...extra });

const text = (r: TextRun, style?: Style): TextNode =>
  style ? { type: 'text', runs: [r], style } : { type: 'text', runs: [r] };

const box = (style: Style, ...children: Node[]): BoxNode =>
  children.length ? { type: 'box', style, children } : { type: 'box', style };

const edges = <T>(v: T) => ({ top: v, right: v, bottom: v, left: v });

const money = (v: number) =>
  '€' + v.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });

const ITEMS: [string, string, number, number][] = [
  ['Engine licence — annual', 'Inkoxide PDF engine, production use, 1 server', 1, 1200.0],
  ['Integration support', 'Remote pairing sessions (hours)', 6, 95.0],
  ['Custom font onboarding', 'Validation and embedding of 4 corporate typefaces', 4, 45.0],
  ['Priority SLA', 'Next-business-day response, 12 months', 1, 480.0],
  ['Training workshop', 'Half-day workshop for the document team', 1, 650.0],
];
const COLS: [string, number | null][] = [
  ['Description', null],
  ['Qty', 40],
  ['Unit price', 70],
  ['Amount', 80],
];

function cell(content: string, width: number | null, align: 'left' | 'right' = 'left', bold = false, color = INK) {
  const style: Style = width === null ? { flexGrow: 1, flexBasis: 0 } : { width };
  return box(style, text(run(content, bold ? 'Inter-Bold' : 'Inter-Regular', 9, color), { textAlign: align }));
}

const rowStyle: Style = {
  flexDirection: 'row',
  gap: 10,
  padding: { top: 8, bottom: 8, left: 10, right: 10 },
  borderWidth: { bottom: 1 },
  borderColor: { bottom: LINE },
};

const headerRow = box(
  { ...rowStyle, padding: { top: 7, bottom: 7, left: 10, right: 10 }, backgroundColor: WASH },
  ...COLS.map(([name, w], i) => cell(name.toUpperCase(), w, i === 0 ? 'left' : 'right', true, MUTED)),
);

const rows = ITEMS.map(([title, desc, qty, price]) =>
  box(
    rowStyle,
    box(
      { flexGrow: 1, flexBasis: 0 },
      text(run(title, 'Inter-Bold', 9.5)),
      text(run(desc, 'Inter-Regular', 8.5, MUTED), { margin: { top: 2 } }),
    ),
    cell(String(qty), 40, 'right'),
    cell(money(price), 70, 'right'),
    cell(money(qty * price), 80, 'right', true),
  ),
);

const subtotal = ITEMS.reduce((s, [, , q, p]) => s + q * p, 0);
const vat = Math.round(subtotal * 0.19 * 100) / 100;

const totalLine = (label: string, value: string, strong = false) =>
  box(
    { flexDirection: 'row', justifyContent: 'space-between' },
    text(run(label, strong ? 'Inter-Bold' : 'Inter-Regular', strong ? 10 : 9, strong ? INK : MUTED)),
    text(run(value, strong ? 'Inter-Bold' : 'Inter-Regular', strong ? 10 : 9)),
  );

const label = (t: string, margin: Style['margin']) =>
  text(run(t, 'Inter-Bold', 7.5, MUTED, { letterSpacing: 0.6 }), { margin });

const party = (title: string, [first, ...rest]: string[]) =>
  box(
    { flexGrow: 1, flexBasis: 0 },
    label(title.toUpperCase(), { bottom: 4 }),
    text(run(first, 'Inter-Bold', 10)),
    ...rest.map((l) => text(run(l, 'Inter-Regular', 9, MUTED), { margin: { top: 1 } })),
  );

export const invoice: Document = {
  version: 1,
  meta: { title: 'Invoice INV-2026-0142', author: 'Inkoxide SRL', lang: 'en' },
  fonts: [
    { id: 'Inter-Regular', family: 'Inter' },
    { id: 'Inter-Bold', family: 'Inter', weight: 700 },
  ],
  pages: [
    {
      size: { width: 595.28, height: 841.89 },
      margin: edges(48),
      children: [
        box(
          { flexDirection: 'row', justifyContent: 'space-between', alignItems: 'flex-start', margin: { bottom: 28 } },
          box(
            { flexDirection: 'row', alignItems: 'center', gap: 8 },
            box({ width: 26, height: 26, backgroundColor: ACCENT, borderRadius: 6 }),
            text(run('Inkoxide', 'Inter-Bold', 16)),
          ),
          box(
            { alignItems: 'flex-end' },
            text(run('INVOICE', 'Inter-Bold', 20, ACCENT, { letterSpacing: 1.5 }), { textAlign: 'right' }),
            text(run('INV-2026-0142', 'Inter-Regular', 10, MUTED), { textAlign: 'right' }),
          ),
        ),
        box(
          { flexDirection: 'row', gap: 20, margin: { bottom: 28 } },
          party('Billed to', ['Studio Nord SRL', 'Str. Ion Câmpineanu 11', '010031 București, România', 'CUI RO12345678']),
          party('From', ['Inkoxide SRL', 'Bd. Eroilor 25', '400129 Cluj-Napoca, România', 'CUI RO87654321']),
          box(
            { width: 110 },
            label('ISSUED', { bottom: 4 }),
            text(run('8 October 2026')),
            label('DUE', { top: 8, bottom: 4 }),
            text(run('7 November 2026')),
          ),
        ),
        box(
          { borderWidth: edges(1), borderColor: edges(LINE), borderRadius: 6, overflow: 'hidden' },
          headerRow,
          ...rows,
        ),
        box(
          { flexDirection: 'row', justifyContent: 'flex-end', margin: { top: 16 } },
          box(
            { width: 210, gap: 6, padding: edges(12), backgroundColor: WASH, borderRadius: 6 },
            totalLine('Subtotal', money(subtotal)),
            totalLine('VAT 19%', money(vat)),
            box({ height: 1, backgroundColor: LINE, margin: { top: 2, bottom: 2 } }),
            totalLine('Total due', money(subtotal + vat), true),
          ),
        ),
        box({ flexGrow: 1 }),
        box(
          { borderWidth: { top: 1 }, borderColor: { top: LINE }, padding: { top: 12 } },
          text(run('Payment details', 'Inter-Bold', 9), { margin: { bottom: 3 } }),
          text(run('IBAN RO49 AAAA 1B31 0075 9384 0000 · BIC AAAARO2X · Reference INV-2026-0142', 'Inter-Regular', 8.5, MUTED)),
          text(
            run(
              'Thank you for your business. Late payments accrue interest of 0.02% per day as per the agreement.',
              'Inter-Regular',
              8.5,
              MUTED,
            ),
            { margin: { top: 6 }, lineHeight: 1.4 },
          ),
        ),
      ],
    },
  ],
};
